insert into public.foods
  (slug, name_en, name_ar, name_eg, food_group, food_state, is_recipe, country_region,
   confidence, human_reviewed, source_rank)
select f.slug, f.en, f.ar, f.eg, 'dish', f.state, true, 'EG', 0.50, false, 50
from f
on conflict (slug) do nothing;

-- Composites 0017 seeded as plain foods. USDA has no basbousa, and a
-- hand-typed row would break the one rule this graph has, so they become
-- recipes. The food_group stays (sweet, drink): the recipe flag is what the
-- resolver and the ingest read.
update public.foods
   set is_recipe = true
 where slug in ('feteer', 'karkade', 'tamr_hindi', 'sobia', 'mango_juice', 'basbousa', 'konafa', 'om_ali', 'rice_pudding', 'mahalabia', 'balah_el_sham', 'zalabia')
   and not is_recipe;

-- ---------------------------------------------------------------------
-- 3. Aliases
-- ---------------------------------------------------------------------
-- Matching is alias-to-phrase (see 0029), so a name a user might type that no
-- alias carries contributes nothing. Hence the generosity: transliterations,
-- the Modern Standard form, the fast-food name, and the spellings people
-- actually produce.

