-- NOT EXISTS rather than ON CONFLICT, as in 0017: the unique constraint
-- carries `note`, which is often null, and nulls never conflict.
insert into public.recipe_ingredients (recipe_id, ingredient_food_id, grams, sort_order, note)
select r.qamar_food_id, i.qamar_food_id, ri.grams, ri.ord, ri.note
from ri
join public.foods r on r.slug = ri.recipe
join public.foods i on i.slug = ri.ingredient
where not exists (
  select 1 from public.recipe_ingredients x
  where x.recipe_id = r.qamar_food_id and x.ingredient_food_id = i.qamar_food_id
);

-- ---------------------------------------------------------------------
-- 5. Portions
-- ---------------------------------------------------------------------
-- A dish's household portion is its recipe: the label is authored, the gram
-- weight is the ingredient total times the yield factor. Deriving it keeps
-- the portion and the recipe from drifting apart when either is corrected.
-- A food that already had a default portion keeps it; the derived one is
-- added alongside, never as a second default.

