yield as (
  select ri.recipe_id, round(sum(ri.grams) * max(r.loss_gain_factor)) as grams
  from public.recipe_ingredients ri
  join public.recipes r on r.qamar_food_id = ri.recipe_id
  group by ri.recipe_id
)
insert into public.food_portions
  (qamar_food_id, label_en, label_ar, grams, is_household, is_default, basis, confidence, source_id)
select fo.qamar_food_id, p.label_en, p.label_ar, y.grams, true,
       not exists (select 1 from public.food_portions d where d.qamar_food_id = fo.qamar_food_id and d.is_default),
       'yield', 0.50, null
from p
join public.foods fo on fo.slug = p.slug
join yield y on y.recipe_id = fo.qamar_food_id
on conflict (qamar_food_id, label_en) do nothing;

