insert into public.food_portions
  (qamar_food_id, label_en, label_ar, grams, is_household, is_default, basis, confidence, source_id)
select fo.qamar_food_id, p.label_en, p.label_ar, p.grams, true,
       p.is_default and not exists (select 1 from public.food_portions d where d.qamar_food_id = fo.qamar_food_id and d.is_default),
       'estimated', 0.50, null
from p join public.foods fo on fo.slug = p.slug
on conflict (qamar_food_id, label_en) do nothing;

-- ---------------------------------------------------------------------
-- 6. Contested names, levelled
-- ---------------------------------------------------------------------
-- 0028 asked for this to be re-run after any alias import. Several stews
-- are named for their vegetable — بامية, فاصوليا, بسلة, لوبيا, سبانخ,
-- قلقاس — and in a meal log the bare word means the cooked dish while the
-- ingredient row keeps the word too. Levelling the priorities marks the name
-- contested; 0027's tie-break then offers the dish first and graph.ts reports
-- the ingredient as "could also be".

with contested as (
  select a.alias, max(a.priority) as top
  from public.food_aliases a
  join public.foods f on f.qamar_food_id = a.qamar_food_id
  group by a.alias
  having count(distinct f.is_recipe) > 1
)
update public.food_aliases a
   set priority = c.top
  from contested c
 where a.alias = c.alias
   and a.priority <> c.top;

-- ---------------------------------------------------------------------
-- 7. Diet flags and allergens, derived from the ingredients
-- ---------------------------------------------------------------------
-- A dish is vegan when every ingredient is, contains gluten when any does,
-- and carries the union of its ingredients' allergens. NULL stays "not
-- established": an ingredient nobody has classified does not make the dish
-- safe. Run three times so a sandwich that contains a dish that contains raw
-- ingredients settles, whatever order the rows come in.

do $$
begin
  for i in 1..3 loop
    update public.foods f
       set is_vegan = d.vegan,
           is_vegetarian = d.vegetarian,
           is_pescatarian = d.pescatarian,
           contains_gluten = d.gluten,
           allergens = d.allergens
      from (
        select ri.recipe_id,
               case when bool_or(i.is_vegan = false) then false
                    when bool_or(i.is_vegan is null) then null else true end as vegan,
               case when bool_or(i.is_vegetarian = false) then false
                    when bool_or(i.is_vegetarian is null) then null else true end as vegetarian,
               -- Pescatarian: vegetarian ingredients plus fish and shellfish.
               case when bool_or(i.is_vegetarian = false and not ('fish' = any(i.allergens) or 'shellfish' = any(i.allergens))) then false
                    when bool_or(i.is_vegetarian is null) then null else true end as pescatarian,
               case when bool_or(i.contains_gluten = true) then true
                    when bool_or(i.contains_gluten is null) then null else false end as gluten,
               coalesce((select array_agg(distinct x order by x)
                           from public.recipe_ingredients ri2
                           join public.foods i2 on i2.qamar_food_id = ri2.ingredient_food_id
                           cross join unnest(i2.allergens) x
                          where ri2.recipe_id = ri.recipe_id), '{}') as allergens
        from public.recipe_ingredients ri
        join public.foods i on i.qamar_food_id = ri.ingredient_food_id
        group by ri.recipe_id
      ) d
     where f.qamar_food_id = d.recipe_id
       and f.is_recipe
       and (f.is_vegan is distinct from d.vegan
         or f.is_vegetarian is distinct from d.vegetarian
         or f.is_pescatarian is distinct from d.pescatarian
         or f.contains_gluten is distinct from d.gluten
         or f.allergens is distinct from d.allergens);
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- 8. Derivation that follows a recipe into a recipe, and refuses to guess
-- ---------------------------------------------------------------------
-- Two changes to 0018's function, both forced by the dishes above.
--
-- Nesting. A taameya sandwich is bread plus taameya, and taameya is itself a
-- recipe with no direct nutrient rows. 0018 read only food_nutrients for each
-- ingredient, so the taameya would have contributed nothing and the sandwich
-- would have been priced as bread and pickles. The function now asks itself
-- for each ingredient's per-100g values, so a sub-recipe answers with its own
-- derivation. Depth is bounded by the data (two levels today); a recipe
-- listing itself is excluded so a bad row cannot recurse forever.
--
-- The gate. 0018 summed whatever ingredients had values and divided by the
-- whole plate, so koshary with only its rice ingested would have been a
-- confident 40 kcal per 100 g — a wrong number that the caller would treat
-- as measured. A missing energy value on any non-optional ingredient now
-- means the dish returns nothing, which graph.ts already treats as a miss
-- and falls back on. dish_nutrient_readiness, below, says which ingredient
-- is the hole.

create or replace function public.qamar_nutrients_per_100g(p_food_id uuid)
returns table (
  nutrient_code text,
  amount numeric,
  unit text,
  source_id text,
  confidence numeric,
  derived boolean
)
language sql
stable
set search_path = public
as $$
  with f as (select is_recipe from public.foods where qamar_food_id = p_food_id),

  direct as (
    select n.nutrient_code, n.amount, nu.unit, n.source_id, n.confidence, false as derived
    from public.food_nutrients n
    join public.nutrients nu on nu.code = n.nutrient_code
    where n.qamar_food_id = p_food_id and n.per_basis = 'per_100g'
  ),

  yield as (
    select sum(ri.grams) * coalesce(max(r.loss_gain_factor), 1) as output_g
    from public.recipe_ingredients ri
    join public.recipes r on r.qamar_food_id = ri.recipe_id
    where ri.recipe_id = p_food_id
  ),

  -- Every ingredient with its own per-100g values: direct rows for a raw
  -- ingredient, a derivation for a sub-recipe. An ingredient with no values
  -- at all still appears, once, with null codes — that is what the gate reads.
  parts as (
    select ri.ingredient_food_id, ri.grams, ri.is_optional,
           n.nutrient_code, n.amount, n.unit, n.confidence
    from public.recipe_ingredients ri
    left join lateral public.qamar_nutrients_per_100g(ri.ingredient_food_id) n on true
    where ri.recipe_id = p_food_id
      and ri.ingredient_food_id <> p_food_id
  ),

  holes as (
    select count(distinct p.ingredient_food_id) as n
    from parts p
    where not p.is_optional
      and not exists (
        select 1 from parts e
        where e.ingredient_food_id = p.ingredient_food_id and e.nutrient_code = 'energy_kcal')
  ),

  computed as (
    select p.nutrient_code,
           round((sum(p.amount * p.grams / 100.0) / nullif((select output_g from yield), 0) * 100)::numeric, 4) as amount,
           max(p.unit) as unit,
           'derived_recipe'::text as source_id,
           -- Never more certain than the weakest ingredient, less the yield
           -- factor's own error.
           round((min(coalesce(p.confidence, 0.5)) * 0.9)::numeric, 2) as confidence,
           true as derived
    from parts p
    where p.nutrient_code is not null
    group by p.nutrient_code
  )

  select * from direct
  union all
  select c.nutrient_code, c.amount, c.unit, c.source_id, c.confidence, c.derived
  from computed c
  where (select is_recipe from f)
    and (select n from holes) = 0
    and not exists (select 1 from direct d where d.nutrient_code = c.nutrient_code);
$$;

comment on function public.qamar_nutrients_per_100g is
  'Per-100g nutrition for a food. A recipe with no direct values is computed '
  'from its ingredients and yield factor, following sub-recipes, and marked '
  'derived with a confidence no higher than its weakest ingredient. Returns '
  'nothing when any non-optional ingredient lacks an energy value, which the '
  'caller must treat as a miss and fall back on — never as zero. See 0051.';

-- Which dishes can be priced today, and which ingredient stops the rest.
-- This is the worklist for ingest_usda.ts after this migration: every slug in
-- missing_ingredients either needs its USDA match or a hand-mapped fdc_id.
create or replace view public.dish_nutrient_readiness
with (security_invoker = true) as
select
  f.slug,
  f.name_eg,
  exists (select 1 from public.qamar_nutrients_per_100g(f.qamar_food_id) n
           where n.nutrient_code = 'energy_kcal') as computable,
  (select string_agg(i.slug, ', ' order by i.slug)
     from public.recipe_ingredients ri
     join public.foods i on i.qamar_food_id = ri.ingredient_food_id
    where ri.recipe_id = f.qamar_food_id
      and not ri.is_optional
      and not exists (select 1 from public.qamar_nutrients_per_100g(i.qamar_food_id) n
                       where n.nutrient_code = 'energy_kcal')) as missing_ingredients,
  (select count(*) from public.recipe_ingredients ri where ri.recipe_id = f.qamar_food_id) as ingredients,
  position('REVIEW:' in coalesce(r.household_note, '')) > 0 as needs_review
from public.foods f
join public.recipes r on r.qamar_food_id = f.qamar_food_id
where f.is_recipe
order by computable, f.slug;

comment on view public.dish_nutrient_readiness is
  'One row per recipe dish. computable = false means qamar_nutrients_per_100g '
  'returns nothing for it, and missing_ingredients names why. needs_review '
  'marks recipes whose proportions the seed flagged for a nutritionist.';

revoke all on public.dish_nutrient_readiness from anon, authenticated;

-- ---------------------------------------------------------------------
-- 9. Eval cases
-- ---------------------------------------------------------------------
-- The accuracy number the kill line is measured on comes from the eval suite,
-- so every dish lands with a case. Bare Egyptian names are generated from the
-- rows themselves — the expectation "a dish resolves by the name we gave it"
-- is written from what should happen, not read back from the resolver — and
-- the contested names, misspellings and transliterations that matter most
-- are written out by hand.

